import React from 'react'
import background from '../../images/background.jpg'

function LandingBanner() {
    return (
        <div
            className="w-full relative pt-[56.25%] bg-cover bg-center"
            style={{ backgroundImage: `url(${background})` }}
        >
            {/* Абсолютный контейнер поверх фонового блока */}
            <div className="absolute top-0 left-0 w-full h-full flex flex-col">
                <div className="stats flex-1 bg-white/50 grid grid-cols-12"> {/* верхняя половина */}
                    <div className="col-span-3 flex justify-center"><h2>35,000$</h2></div>
                    <div className="col-span-9"><h2>COL-9</h2></div>
                </div>
                <div className="title flex-1 bg-black/50 text-white"> {/* нижняя половина */}
                    Заголовок
                </div>
            </div>
        </div>
    )
}

export default LandingBanner
